namespace {int checks=0;void check(bool condition,const char* message){++checks;if(!condition)throw std::runtime_error(message);}}
int main(){try{
    auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"teacher","student"};catalog->places.insert("home",{"home","town",{}});RoleDefinition role;role.id="teacher_role";role.initial_actor="teacher";role.place_id="home";catalog->roles.insert(role.id,role);
    CommonState initial;initial.identity.world_id[0]=7;initial.identity.execution_epoch=3;initial.identity.revision=5;initial.identity.tick=20;initial.metadata.player_actor_id="student";initial.metadata.scenario_id="apprenticeship";initial.next_instance_id=100;initial.roles.insert(role.id,{"teacher",true,{}});
    for(const auto* id:{"teacher","student"}){ActorRecord a;a.id=id;a.birth_tick=20-18*720;a.alive=a.available=true;a.hp=100;a.location=SettlementLocation{"town","home"};initial.actors.insert(id,a);}
    initial.facts.insert("apprenticeship:9",{"apprenticeship:9","family_apprenticeship_proposed","family_apprenticeship"});CommonStore common(initial,catalog);
    InteractionCatalog interactions;interactions.common=catalog;DialogueDefinition dialogue;dialogue.id="offer";dialogue.context_role=role.id;dialogue.entry="say";DialogueNode node;node.id="say";node.kind="say";node.speaker="$provider";dialogue.nodes.push_back(node);node.id="end";dialogue.nodes.push_back(node);interactions.dialogues.push_back(dialogue);
    InteractionState meeting;InteractionSession session;session.id="interaction:3";session.actor_id="student";session.dialogue_id="offer";session.node_id="say";session.phase="say";session.context={"home","teacher",role.id};meeting.interactions.push_back(session);
    InteractionAccess access;access.battle_occupied=[](const StableId&){return false;};access.resolve_location=[&](const StableId& actor){return common.actor(actor)->location;};access.role=[&](const StableId& name)->std::optional<RoleAssignmentView>{const auto* r=common.state().roles.find(name);return r?std::optional<RoleAssignmentView>{{r->actor_id,r->enabled}}:std::nullopt;};
    ApprenticeshipCatalog definitions;definitions.enabled=true;ApprenticeshipStatementDefinition d;d.id="offer_commerce";d.speaker_actor_id="teacher";d.speaker_side="teacher";d.skill_id="commerce";d.dialogue_id="offer";d.node_id="say";definitions.statements.insert(d.id,d);
    ApprenticeshipIdentityRead people;people.player_before=[](Integer,const StableId&)->Outcome<StableId>{return {true,"student",{}};};people.personally_available=[](const StableId&,Integer,const StableId&){return common_success();};
    const auto before=encode_common_state(common.state());auto quote=preview_apprenticeship_statement(common,meeting,interactions,access,definitions,people,"student",d.id);check(quote.ok,"actual teacher say must produce only source");check(quote.value.source.teacher_actor_id=="teacher"&&quote.value.source.student_actor_id=="student","sides must remain exact original people");check(revalidate_apprenticeship_statement(common,meeting,interactions,access,definitions,people,quote.value).ok,"same current node revalidates");check(validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,quote.value.source,"apprenticeship:9").ok,"exact historical person source");check(compare_boundary(before,encode_common_state(common.state())).exact(),"pure source read changes no Common or XP");
    meeting.interactions[0].node_id="end";check(!revalidate_apprenticeship_statement(common,meeting,interactions,access,definitions,people,quote.value).ok,"leaving source node revokes current quote");meeting.interactions[0].node_id="say";
    for(const auto* wrong:{"$player","student",""}){interactions.dialogues.front().nodes.front().speaker=wrong;check(!preview_apprenticeship_statement(common,meeting,interactions,access,definitions,people,"student",d.id).ok,"player or third speaker cannot sign NPC apprenticeship");check(!validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,quote.value.source,"apprenticeship:9").ok,"cold NPC source cannot relabel player say");}interactions.dialogues.front().nodes.front().speaker="$provider";
    auto altered=quote.value.source;altered.teacher_actor_id="student";check(!validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,altered,"apprenticeship:9").ok,"cannot swap role into teacher authority");altered=quote.value.source;altered.world_id[0]=8;check(!validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,altered,"apprenticeship:9").ok,"other world cannot authorize relation");
    common.state().actors.find("student")->birth_tick=21-18*720;check(!preview_apprenticeship_statement(common,meeting,interactions,access,definitions,people,"student",d.id).ok,"under18 adult route rejects");common.state().actors.find("student")->birth_tick=20-18*720;
    auto missing=people;missing.personally_available={};check(!preview_apprenticeship_statement(common,meeting,interactions,access,definitions,missing,"student",d.id).ok,"missing military availability source is not free");
    auto encoded=encode_apprenticeship_statement_source(quote.value.source);auto decoded=decode_apprenticeship_statement_source(encoded);check(decoded.ok&&apprenticeship_source_equal(decoded.value,quote.value.source),"strict source roundtrip");using V=BoundaryValue;encoded.as<V::Dict>()->emplace_back("student_actor_id",V{"teacher"});check(!decode_apprenticeship_statement_source(encoded).ok,"root duplicate source rejected before first match");encoded=encode_apprenticeship_statement_source(quote.value.source);encoded.find("context")->as<V::Dict>()->emplace_back("provider_actor_id",V{"student"});check(!decode_apprenticeship_statement_source(encoded).ok,"nested duplicate rejected");encoded=encode_apprenticeship_statement_source(quote.value.source);encoded.as<V::Dict>()->emplace_back("inherit_assets",V{true});check(!decode_apprenticeship_statement_source(encoded).ok,"relation cannot hide assets grant");
    auto bad=definitions;auto second=d;second.id="ambiguous";second.listener_actor_id="student";bad.statements.insert(second.id,second);check(!validate_apprenticeship_catalog(bad,*catalog,interactions).ok,"generic and directed source cannot overlap");
    // 当今死亡不抹先前真实师承节点，先死后登记也不能给新关系补签。
    common.state().facts.insert("military:10",{"military:10","military_casualties","military"});common.state().facts.insert("apprenticeship:11",{"apprenticeship:11","family_apprenticeship_proposed","family_apprenticeship"});common.state().actors.find("teacher")->alive=false;people.death_origin=[](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{if(actor=="teacher")return {true,FamilyDeathOrigin{"teacher","military:10","battle",20},{}};return {true,std::nullopt,{}};};check(validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,quote.value.source,"apprenticeship:9").ok,"later death retains earlier true source");check(!validate_apprenticeship_statement_source(common,*catalog,interactions,definitions,people,quote.value.source,"apprenticeship:11").ok,"same tick cause before decision forbids consent");
    std::cout<<"APPRENTICESHIP_SOURCE "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"APPRENTICESHIP_SOURCE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
